cat > /tmp/prune_keys.py <<'PY'
import sys, re, os, glob, yaml, collections

def parse(path):
    """Return list of (indent, key, lineno) for mapping entries, plus raw lines."""
    with open(path, encoding="utf-8") as f:
        lines = f.readlines()
    entries = []
    for i, line in enumerate(lines):
        m = re.match(r'^(\s*)([^\s#][^:]*):\s*(.*)$', line.rstrip("\n"))
        if not m:
            continue
        indent, key, rest = m.groups()
        if key.startswith("-"):
            continue
        entries.append((len(indent), key, i, rest))
    return lines, entries

def build(entries, start, end):
    """Build nested structure of (indent, key, lineno, children, rest) for lines[start..end)."""
    root = []
    stack = []
    idx = start
    while idx < end:
        indent, key, lineno, rest = entries[idx]
        node = [indent, key, lineno, [], rest]
        while stack and stack[-1][0] >= indent:
            stack.pop()
        if stack:
            stack[-1][3].append(node)
        else:
            root.append(node)
        stack.append(node)
        idx += 1
    return root

def collect_leaves(node, prefix, out):
    path = prefix + [node[1]]
    if not node[3]:
        out.append((path, node[2]))
    else:
        for c in node[3]:
            collect_leaves(c, path, out)

def main(target_keys_file, base_dir):
    with open(target_keys_file) as f:
        targets = set(l.strip() for l in f if l.strip())
    files = sorted(glob.glob(os.path.join(base_dir, "*.yml")))
    # map each target key to its file by scanning
    key_to_file = {}
    for path in files:
        lines, entries = parse(path)
        root = build(entries, 0, len(entries))
        leaves = []
        for n in root:
            collect_leaves(n, [], leaves)
        for p, lineno in leaves:
            key = ".".join(p[1:])
            if key in targets and key not in key_to_file:
                key_to_file[key] = path
    missing = targets - set(key_to_file)
    print("NOT FOUND:", sorted(missing))
    by_file = collections.defaultdict(set)
    for k, f in key_to_file.items():
        by_file[f].add(k)
    for path, keys in sorted(by_file.items()):
        prune(path, keys)

def prune(path, keys):
    lines, entries = parse(path)
    root = build(entries, 0, len(entries))
    to_delete = set()
    def walk(node, prefix):
        pathk = prefix + [node[1]]
        key = ".".join(pathk[1:])
        if node[3]:
            all_del = True
            for c in node[3]:
                walk(c, pathk)
            # after children processed
            for c in node[3]:
                if c[2] not in to_delete:
                    all_del = False
            if all_del:
                to_delete.add(node[2])
        else:
            if key in keys:
                to_delete.add(node[2])
    for n in root:
        walk(n, [])
    new = [l for i, l in enumerate(lines) if i not in to_delete]
    # remove resulting consecutive blank lines
    out = []
    prev_blank = False
    for l in new:
        blank = l.strip() == ""
        if blank and prev_blank:
            continue
        out.append(l)
        prev_blank = blank
    open(path, "w", encoding="utf-8").write("".join(out))
    print(f"{path}: removed {len(to_delete)} lines for {len(keys)} keys")

main(sys.argv[1], sys.argv[2])
PY
