def main2(target_keys_file, base_dir):
    targets = set(l.strip() for l in open(target_keys_file) if l.strip())
    files = sorted(glob.glob(os.path.join(base_dir, "*.yml")))
    found = {}
    for path in files:
        lines, entries = parse(path)
        root = build(entries, 0, len(entries))
        leaves = []
        for n in root:
            collect_leaves(n, [], leaves)
        for p, lineno in leaves:
            for pref in [p, p[:-1]]:
                key = ".".join(pref[1:])
                if key in targets and key not in found:
                    found[key] = (path, tuple(pref))
    missing = targets - set(found)
    print("STILL NOT FOUND:", sorted(missing))
    by_file = collections.defaultdict(dict)
    for k, (path, pref) in found.items():
        by_file[path][k] = pref
    for path, d in sorted(by_file.items()):
        prune_paths(path, d)

def prune_paths(path, wanted):
    """wanted: key -> tuple(path components incl. root locale)"""
    lines, entries = parse(path)
    root = build(entries, 0, len(entries))
    to_delete = set()
    prefixes = set(wanted.values())
    def walk(node, prefix):
        pathk = prefix + [node[1]]
        if tuple(pathk) in prefixes:
            mark(node)
            return
        for c in node[3]:
            walk(c, pathk)
    def mark(node):
        to_delete.add(node[2])
        for c in node[3]:
            mark(c)
    for n in root:
        walk(n, [])
    new = [l for i, l in enumerate(lines) if i not in to_delete]
    out = []
    prev_blank = False
    for l in new:
        blank = l.strip() == ""
        if blank and prev_blank:
            continue
        out.append(l)
        prev_blank = blank
    open(path, "w", encoding="utf-8").write("".join(out))
    print(f"{path}: removed {len(to_delete)} lines")

main2(sys.argv[1], sys.argv[2])
